const fifteenMinutesAgo = $now
  .minus({ minutes: 30 })
  .toFormat("yyyy-MM-dd'T'HH:mm:ss");

return [
  {
    json: {
      fifteenMinutesAgo
    }
  }
];

return items.map(item => {
  const timeZoneText = item.json.time_zone;

  // Example input:
  // "(UTC+09:30) Adelaide"
  // "(UTC+10:00) Brisbane"
  const match = timeZoneText.match(/UTC([+-])(\d{2}):(\d{2})/);

  if (!match) {
    throw new Error(`Could not read timezone from: ${timeZoneText}`);
  }

  const sign = match[1] === "+" ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);

  const offsetMinutes = sign * ((hours * 60) + minutes);

  const clinicTimeMinus15 = $now
    .toUTC()
    .plus({ minutes: offsetMinutes })
    .minus({ minutes: 15 })
    .toFormat("yyyy-MM-dd'T'HH:mm:ss");

  item.json.clinic_time_minus_15 = clinicTimeMinus15;

  return item;
});

const items = $input.all();

const escapeHtml = (value) => {
  if (value === null || value === undefined) return "";
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
};

const rows = items.map(item => {
  const data = item.json;

  const centerName = data.center_name;
  const guestName = data.guest?.guest_name;
  const guestCode = data.guest?.guest_code;
  const directLink = data.directlink;

  return `
    <tr>
      <td>${escapeHtml(centerName)}</td>
      <td>${escapeHtml(guestName)}</td>
      <td>${escapeHtml(guestCode)}</td>
      <td><a href="${escapeHtml(directLink)}">Open Opportunity</a></td>
    </tr>
  `;
}).join("");

const htmlTable = `
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse; font-family: Arial, sans-serif; font-size: 13px;">
  <thead>
    <tr style="background-color: #f2f2f2;">
      <th>Center</th>
      <th>Guest Name</th>
      <th>Guest Code</th>
      <th>Link</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
`;

return [
  {
    json: {
      htmlTable,
      recordCount: items.length
    }
  }
];

return items.map(item => {
  const timeZoneText = item.json.time_zone;

  // Example input:
  // "(UTC+09:30) Adelaide"
  // "(UTC+10:00) Brisbane"
  const match = timeZoneText.match(/UTC([+-])(\d{2}):(\d{2})/);

  if (!match) {
    throw new Error(`Could not read timezone from: ${timeZoneText}`);
  }

  const sign = match[1] === "+" ? 1 : -1;
  const hours = parseInt(match[2], 10);
  const minutes = parseInt(match[3], 10);

  const offsetMinutes = sign * ((hours * 60) + minutes);

  const clinicTimeMinus15 = $now
    .toUTC()
    .plus({ minutes: offsetMinutes })
    .minus({ minutes: 15 })
    .toFormat("yyyy-MM-dd'T'HH:mm:ss");

  item.json.clinic_time_minus_15 = clinicTimeMinus15;

  return item;
});

